insert into new_text values
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'de', 'description', $t$Eine Börse für altes Sammlerspielzeug, mit 400 Tischen. Vor Ort gibt es ein Restaurant, Kaffee und Sandwiches. Organisiert wird sie von Dakota Events, einem Familienbetrieb. Am selben Wochenende findet im Forum Fribourg auch deren Börse für Fotoapparate, alte Papiere, Bücher und Schallplatten statt.$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'en', 'description', $t$A fair for old collectors' toys, with 400 tables. There is a restaurant on site, with coffee and sandwiches. It is run by Dakota Events, a family business. The same weekend, Forum Fribourg also hosts their fair for cameras, old paper, books and records.$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'fr', 'description', $t$Une bourse de vieux jouets de collection, sur 400 tables. Sur place, un restaurant propose café et sandwichs. Elle est organisée par Dakota Events, une entreprise familiale. Le même week-end, Forum Fribourg accueille aussi leur bourse d'appareils photo, de vieux papiers, de livres et de vinyles.$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'it', 'description', $t$Una borsa di vecchi giocattoli da collezione, su 400 tavoli. Sul posto c'è un ristorante, con caffè e panini. La organizza Dakota Events, un'azienda di famiglia. Lo stesso fine settimana il Forum Fribourg ospita anche la loro borsa di macchine fotografiche, carte d'epoca, libri e vinili.$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'en', 'recurrence_text', $t$One Saturday in February$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'fr', 'recurrence_text', $t$Un samedi de février$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'it', 'recurrence_text', $t$Un sabato di febbraio$t$),
  ($t$bourse-jouets-collection-geneve-le-grand-saconnex$t$, 'de', 'description', $t$Die 30. Ausgabe dieser Börse für Sammlerspielzeug in der Palexpo. Sie findet gemeinsam mit der Vinyl- und CD-Börse statt; zusammen sind es über 200 Tische. Es gibt eine Buvette und kleine Speisen.$t$),
  ($t$bourse-jouets-collection-geneve-le-grand-saconnex$t$, 'en', 'description', $t$The 30th edition of this collectors' toy fair at Palexpo. It runs together with the record and CD fair, with more than 200 tables between them. There is a bar with light food.$t$),
  ($t$bourse-jouets-collection-geneve-le-grand-saconnex$t$, 'fr', 'description', $t$La 30e édition de cette bourse de jouets de collection à Palexpo. Elle se tient avec la bourse de vinyles et CD, et l'ensemble compte plus de 200 tables. Buvette et petite restauration sur place.$t$),
  ($t$bourse-jouets-collection-geneve-le-grand-saconnex$t$, 'it', 'description', $t$La 30ª edizione di questa borsa di giocattoli da collezione al Palexpo. Si svolge insieme alla borsa di vinili e CD, con oltre 200 tavoli in tutto. C'è un bar con piccola ristorazione.$t$),
  ($t$bourse-jouets-collection-geneve-le-grand-saconnex$t$, 'en', 'recurrence_text', $t$One Sunday in January$t$),
  ($t$bourse-jouets-collection-geneve-le-grand-saconnex$t$, 'fr', 'recurrence_text', $t$Un dimanche de janvier$t$),
  ($t$bourse-jouets-collection-geneve-le-grand-saconnex$t$, 'it', 'recurrence_text', $t$Una domenica di gennaio$t$),
  ($t$bourse-photo-vieux-papiers-fribourg-granges-paccot$t$, 'de', 'description', $t$Eine Börse für Fotoapparate und Fotos, Ansichtskarten, alte Papiere, antiquarische Bücher, Comics, Schallplatten und CDs, in der Halle 4 des Forum Fribourg. Am selben Wochenende findet dort auch die Börse für Sammlerspielzeug von Dakota Events statt.$t$),
  ($t$bourse-photo-vieux-papiers-fribourg-granges-paccot$t$, 'en', 'description', $t$A fair for cameras and photographs, postcards, old paper, antiquarian books, comics, records and CDs, in Hall 4 of Forum Fribourg. The same weekend, the venue also hosts Dakota Events' collectors' toy fair.$t$),
  ($t$bourse-photo-vieux-papiers-fribourg-granges-paccot$t$, 'fr', 'description', $t$Une bourse d'appareils photo et de photographies, de cartes postales, de vieux papiers, de livres anciens, de bandes dessinées, de vinyles et de CD, dans la halle 4 de Forum Fribourg. Le même week-end, le lieu accueille aussi la bourse de jouets de collection de Dakota Events.$t$),
  ($t$bourse-photo-vieux-papiers-fribourg-granges-paccot$t$, 'it', 'description', $t$Una borsa di macchine fotografiche e fotografie, cartoline, carte d'epoca, libri antichi, fumetti, dischi in vinile e CD, nella Halle 4 del Forum Fribourg. Lo stesso fine settimana il Forum ospita anche la borsa di giocattoli da collezione di Dakota Events.$t$),
  ($t$bourse-photo-vieux-papiers-fribourg-granges-paccot$t$, 'en', 'recurrence_text', $t$One Sunday in February$t$),
  ($t$bourse-photo-vieux-papiers-fribourg-granges-paccot$t$, 'fr', 'recurrence_text', $t$Un dimanche de février$t$),
  ($t$bourse-photo-vieux-papiers-fribourg-granges-paccot$t$, 'it', 'recurrence_text', $t$Una domenica di febbraio$t$),
  ($t$bourse-vinyls-cd-geneve-le-grand-saconnex$t$, 'de', 'description', $t$Die 5. Ausgabe dieser Börse für Schallplatten und CDs in der Palexpo. Sie teilt den Tag mit der Börse für Sammlerspielzeug; zusammen sind es über 200 Tische.$t$),
  ($t$bourse-vinyls-cd-geneve-le-grand-saconnex$t$, 'en', 'description', $t$The fifth edition of this record and CD fair at Palexpo. It shares the day with the collectors' toy fair, and together they have more than 200 tables.$t$),
  ($t$bourse-vinyls-cd-geneve-le-grand-saconnex$t$, 'fr', 'description', $t$La 5e édition de cette bourse de vinyles et CD à Palexpo. Elle partage la journée avec la bourse de jouets de collection, et les deux réunissent plus de 200 tables.$t$),
  ($t$bourse-vinyls-cd-geneve-le-grand-saconnex$t$, 'it', 'description', $t$La 5ª edizione di questa borsa di vinili e CD al Palexpo. Condivide la giornata con la borsa di giocattoli da collezione, e insieme contano oltre 200 tavoli.$t$),
  ($t$bourse-vinyls-cd-geneve-le-grand-saconnex$t$, 'en', 'recurrence_text', $t$One Sunday in January$t$),
  ($t$bourse-vinyls-cd-geneve-le-grand-saconnex$t$, 'fr', 'recurrence_text', $t$Un dimanche de janvier$t$),
  ($t$bourse-vinyls-cd-geneve-le-grand-saconnex$t$, 'it', 'recurrence_text', $t$Una domenica di gennaio$t$),
  ($t$brocante-de-fribourg-granges-paccot$t$, 'de', 'description', $t$Eine Brocante im Forum Fribourg, organisiert von Dakota Events, einem Familienbetrieb, der auch Börsen für altes Spielzeug veranstaltet.$t$),
  ($t$brocante-de-fribourg-granges-paccot$t$, 'en', 'description', $t$A brocante at Forum Fribourg, run by Dakota Events, a family business that also organises fairs for old toys.$t$),
  ($t$brocante-de-fribourg-granges-paccot$t$, 'fr', 'description', $t$Une brocante à Forum Fribourg, organisée par Dakota Events, une entreprise familiale qui met aussi sur pied des bourses de jouets anciens.$t$),
  ($t$brocante-de-fribourg-granges-paccot$t$, 'it', 'description', $t$Una brocante al Forum Fribourg, organizzata da Dakota Events, un'azienda di famiglia che allestisce anche borse di giocattoli d'epoca.$t$),
  ($t$brocante-de-fribourg-granges-paccot$t$, 'en', 'recurrence_text', $t$One weekend in November$t$),
  ($t$brocante-de-fribourg-granges-paccot$t$, 'fr', 'recurrence_text', $t$Un week-end de novembre$t$),
  ($t$brocante-de-fribourg-granges-paccot$t$, 'it', 'recurrence_text', $t$Un fine settimana di novembre$t$),
  ($t$brocante-vide-grenier-55-plus-ecublens$t$, 'de', 'description', $t$Die 55+ d'Ecublens, ein Verein von Freiwilligen für die über 55-Jährigen der Gemeinde, organisieren diese Brocante mit Vide-grenier. Laut Flyer wird alles günstig verkauft. Es gibt eine Buvette, und alle sind willkommen.$t$),
  ($t$brocante-vide-grenier-55-plus-ecublens$t$, 'en', 'description', $t$Run by the 55+ d'Ecublens, a volunteer association for the town's over-55s, this is a brocante and vide-grenier in one. The flyer says everything goes at low prices. There is a refreshment bar, and everyone is welcome.$t$),
  ($t$brocante-vide-grenier-55-plus-ecublens$t$, 'fr', 'description', $t$Une brocante et vide-grenier organisés par les 55+ d'Ecublens, une association de bénévoles tournée vers les plus de 55 ans de la commune. Tout y est bradé à petit prix, annonce le flyer. Buvette sur place, et tout le monde est bienvenu.$t$),
  ($t$brocante-vide-grenier-55-plus-ecublens$t$, 'it', 'description', $t$Un mercatino dell'usato e svuota-soffitte organizzato dai 55+ d'Ecublens, un'associazione di volontari per gli over 55 del comune. Secondo il volantino, tutto viene venduto a prezzi bassi. C'è un punto ristoro, e tutti sono benvenuti.$t$),
  ($t$brocante-vide-grenier-55-plus-ecublens$t$, 'en', 'recurrence_text', $t$One Saturday in November$t$),
  ($t$brocante-vide-grenier-55-plus-ecublens$t$, 'fr', 'recurrence_text', $t$Un samedi de novembre$t$),
  ($t$brocante-vide-grenier-55-plus-ecublens$t$, 'it', 'recurrence_text', $t$Un sabato di novembre$t$),
  ($t$comicboerse-zuerich$t$, 'de', 'description', $t$Rund um Comics, Mangas und Film wird hier gesammelt, getauscht und gefachsimpelt. Auf 80 Verkaufstischen liegen Figuren, Karten, Originale, Bücher und Hefte, neue wie alte; sie stammen von Privatleuten und Händlern aus Deutschland und der Schweiz. Dazu kommen Künstlerinnen und Künstler, die vor Ort signieren, und die Swiss Garrison erscheint kostümiert.$t$),
  ($t$comicboerse-zuerich$t$, 'en', 'description', $t$Collecting, swapping and talking shop around comics, manga and film. The 80 sales tables hold figures, cards, original art, books and comic books, new as well as old, brought by private sellers and dealers from Germany and Switzerland. Comic artists are there to sign, and the Swiss Garrison comes along in costume.$t$),
  ($t$comicboerse-zuerich$t$, 'fr', 'description', $t$On y collectionne, échange et discute autour de la BD, du manga et du cinéma. Les 80 tables de vente accueillent figurines, cartes, originaux, livres et albums, récents comme anciens, apportés par des particuliers et des marchands venus d'Allemagne et de Suisse. Des dessinateurs dédicacent sur place, et la Swiss Garrison se montre en costume.$t$),
  ($t$comicboerse-zuerich$t$, 'it', 'description', $t$Si colleziona, si scambia e si chiacchiera di fumetti, manga e cinema. Sugli 80 tavoli di vendita ci sono statuine, carte, tavole originali, libri e albi, nuovi e vecchi, portati da privati e commercianti di Germania e Svizzera. Sul posto alcuni artisti autografano i propri fumetti, e la Swiss Garrison si presenta in costume.$t$),
  ($t$comicboerse-zuerich$t$, 'en', 'recurrence_text', $t$Once a year, on a Sunday$t$),
  ($t$comicboerse-zuerich$t$, 'fr', 'recurrence_text', $t$Une fois par an, un dimanche$t$),
  ($t$comicboerse-zuerich$t$, 'it', 'recurrence_text', $t$Una volta all'anno, di domenica$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'de', 'description', $t$Wer Modelle baut, findet hier Bausätze und Zubehör für Flugzeuge, Züge, Autos und mehr. Schauplatz ist die Eventhalle des Technikmuseums Enter Technikwelt, und das Ticket gilt zugleich als Tagespass fürs Museum. Essen gibt es im hauseigenen Restaurant.$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'en', 'description', $t$For people who build models: kits and accessories for aircraft, trains, cars and more. Its home is the event hall at Enter Technikwelt, a technology museum, and the ticket doubles as a day pass to the museum. The museum's own restaurant serves food.$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'fr', 'description', $t$Pour qui construit des maquettes : kits et accessoires pour avions, trains, voitures et bien plus. La bourse se tient dans la salle événementielle de l'Enter Technikwelt, un musée de la technique, et le billet vaut aussi pass journée pour le musée. On mange au restaurant de la maison.$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'it', 'description', $t$Per chi costruisce modelli: kit e accessori per aerei, treni, auto e altro ancora. Ospita la borsa l'Enter Technikwelt, un museo della tecnica, nella sua sala eventi, e il biglietto vale anche come pass giornaliero per il museo. Si mangia al ristorante interno.$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'en', 'recurrence_text', $t$One weekend in December$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'fr', 'recurrence_text', $t$Un week-end de décembre$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'it', 'recurrence_text', $t$Un fine settimana di dicembre$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'de', 'description', $t$Ein Markt für historische Technik, auf dem Privatpersonen und Firmen Sammlerstücke, Occasionen und Liquidationsware anbieten, für Sammler, Handwerker und Bastler. Maschinen und Apparate aller Art: Dampfmaschinen, Motoren, Mess- und medizinische Instrumente, Uhren, Haushaltgeräte, Musik- und Spielautomaten. Dazu Radios, Fernseher, Tonbandgeräte, Plattenspieler, Schreibmaschinen und Computer, Werkzeuge, Ersatzteile und technische Literatur. Es gibt 500 Gratis-Parkplätze, die Haltestelle Derendingen, Freiheit liegt fünf Minuten zu Fuss entfernt.$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'en', 'description', $t$A market for historic technology, where private sellers and companies offer collectors' pieces, second-hand goods and clearance stock to collectors, craftspeople and tinkerers. Machines and devices of every kind: steam engines, motors, measuring and medical instruments, clocks, household appliances, music and coin-operated machines. Also radios, televisions, tape recorders, record players, typewriters and computers, plus tools, spare parts and technical books. There are 500 free parking spaces, and the Derendingen, Freiheit stop is a five-minute walk.$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'fr', 'description', $t$Un marché de la technique d'autrefois, où particuliers et entreprises proposent pièces de collection, occasions et liquidations aux collectionneurs, artisans et bricoleurs. Machines et appareils de tous genres : machines à vapeur, moteurs, instruments de mesure et médicaux, horloges, électroménager, automates musicaux et de jeu. Aussi des radios, téléviseurs, magnétophones, tourne-disques, machines à écrire et ordinateurs, ainsi que des outils, des pièces détachées et de la littérature technique. 500 places de parc gratuites ; l'arrêt Derendingen, Freiheit est à cinq minutes à pied.$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'it', 'description', $t$Un mercato della tecnica storica, dove privati e aziende offrono pezzi da collezione, usato e merce di liquidazione a collezionisti, artigiani e appassionati del fai da te. Macchine e apparecchi di ogni tipo: macchine a vapore, motori, strumenti di misura e medici, orologi, elettrodomestici, automi musicali e macchine da gioco. Poi radio, televisori, registratori a nastro, giradischi, macchine da scrivere e computer, oltre ad attrezzi, ricambi e letteratura tecnica. Ci sono 500 posteggi gratuiti, e la fermata Derendingen, Freiheit è a cinque minuti a piedi.$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'en', 'recurrence_text', $t$One weekend in November$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'fr', 'recurrence_text', $t$Un week-end de novembre$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'it', 'recurrence_text', $t$Un fine settimana di novembre$t$),
  ($t$enter-vinyl-film-buecher-boerse-derendingen$t$, 'de', 'description', $t$Kameras und Filmausrüstung, Bücher, Schallplatten und CDs: An dieser Börse gibt es Seltenes aus der Welt der Medien. Draussen kommt ein Kofferraumflohmarkt dazu, und das Restaurant der Enter Technikwelt serviert Essen.$t$),
  ($t$enter-vinyl-film-buecher-boerse-derendingen$t$, 'en', 'description', $t$Cameras and film gear, books, vinyl and CDs: this fair is about rare finds from the world of media. Outside, a car-boot sale adds to it, and the restaurant at Enter Technikwelt serves food.$t$),
  ($t$enter-vinyl-film-buecher-boerse-derendingen$t$, 'fr', 'description', $t$Appareils photo et matériel de cinéma, livres, vinyles et CD : cette bourse rassemble des raretés du monde des médias. À l'extérieur s'ajoute un vide-coffres, et le restaurant de l'Enter Technikwelt propose à manger.$t$),
  ($t$enter-vinyl-film-buecher-boerse-derendingen$t$, 'it', 'description', $t$Macchine fotografiche e attrezzatura per il cinema, libri, vinili e CD: questa borsa riunisce rarità dal mondo dei media. All'esterno si aggiunge un mercatino dal bagagliaio, e il ristorante dell'Enter Technikwelt offre da mangiare.$t$),
  ($t$enter-vinyl-film-buecher-boerse-derendingen$t$, 'en', 'recurrence_text', $t$One Sunday in February$t$),
  ($t$enter-vinyl-film-buecher-boerse-derendingen$t$, 'fr', 'recurrence_text', $t$Un dimanche de février$t$),
  ($t$enter-vinyl-film-buecher-boerse-derendingen$t$, 'it', 'recurrence_text', $t$Una domenica di febbraio$t$),
  ($t$floh-sammler-antikmarkt-grabs$t$, 'de', 'description', $t$Seit 1999 gibt es auf dem Grabser Marktplatz diesen Markt für Trödel, Sammlerstücke und Antikes. Verpflegung kommt jedes Mal von einem mobilen Imbiss.$t$),
  ($t$floh-sammler-antikmarkt-grabs$t$, 'en', 'description', $t$Since 1999, the Marktplatz in Grabs has hosted this mix of flea market, collectables and antiques. A travelling food stand comes along every time.$t$),
  ($t$floh-sammler-antikmarkt-grabs$t$, 'fr', 'description', $t$Depuis 1999, ce marché mêle puces, objets de collection et antiquités sur la Marktplatz, à Grabs. Un stand de restauration ambulant vient à chaque fois.$t$),
  ($t$floh-sammler-antikmarkt-grabs$t$, 'it', 'description', $t$Dal 1999 questo mercato unisce pulci, collezionismo e antiquariato sulla Marktplatz, a Grabs. Ogni volta è presente uno stand di cibo ambulante.$t$),
  ($t$floh-sammler-antikmarkt-grabs$t$, 'en', 'recurrence_text', $t$Monthly, on a Saturday, March to November$t$),
  ($t$floh-sammler-antikmarkt-grabs$t$, 'fr', 'recurrence_text', $t$Une fois par mois, un samedi, de mars à novembre$t$),
  ($t$floh-sammler-antikmarkt-grabs$t$, 'it', 'recurrence_text', $t$Una volta al mese, di sabato, da marzo a novembre$t$),
  ($t$floh-sammler-antikmarkt-romanshorn$t$, 'de', 'description', $t$Seit 1995 gibt es am Romanshorner Hafen diesen Markt für Trödel, Sammlerstücke und Antikes. Jedes Mal ist ein mobiler Imbiss vor Ort.$t$),
  ($t$floh-sammler-antikmarkt-romanshorn$t$, 'en', 'description', $t$Since 1995, this mix of flea market, collectables and antiques has been held on Romanshorn's harbourfront. A travelling food stand is there every time.$t$),
  ($t$floh-sammler-antikmarkt-romanshorn$t$, 'fr', 'description', $t$Depuis 1995, ce marché mêle puces, objets de collection et antiquités près du port, à Romanshorn. Un stand de restauration ambulant est là à chaque fois.$t$),
  ($t$floh-sammler-antikmarkt-romanshorn$t$, 'it', 'description', $t$Dal 1995 questo mercato unisce pulci, collezionismo e antiquariato vicino al porto, a Romanshorn. Ogni volta c'è uno stand di cibo ambulante.$t$),
  ($t$floh-sammler-antikmarkt-romanshorn$t$, 'en', 'recurrence_text', $t$Monthly, on a Saturday, March to November$t$),
  ($t$floh-sammler-antikmarkt-romanshorn$t$, 'fr', 'recurrence_text', $t$Une fois par mois, un samedi, de mars à novembre$t$),
  ($t$floh-sammler-antikmarkt-romanshorn$t$, 'it', 'recurrence_text', $t$Una volta al mese, di sabato, da marzo a novembre$t$),
  ($t$flohmarkt-ace-cafe-rothenburg$t$, 'de', 'description', $t$Ein Flohmarkt im Ace Cafe Luzern, einem Café, in dem das ganze Jahr über Auto- und Töfftreffen stattfinden. Am Morgen gibt es aus der Küche Frühstück.$t$),
  ($t$flohmarkt-ace-cafe-rothenburg$t$, 'en', 'description', $t$A flea market at the Ace Cafe Luzern, a café that hosts car and motorbike meets all year round. In the morning, the kitchen serves breakfast.$t$),
  ($t$flohmarkt-ace-cafe-rothenburg$t$, 'fr', 'description', $t$Un marché aux puces à l'Ace Cafe Luzern, un café qui accueille toute l'année des rencontres de voitures et de motos. Le matin, la cuisine sert le petit-déjeuner.$t$),
  ($t$flohmarkt-ace-cafe-rothenburg$t$, 'it', 'description', $t$Un mercatino delle pulci all'Ace Cafe Luzern, un caffè che tutto l'anno ospita raduni di auto e moto. Al mattino la cucina serve la colazione.$t$),
  ($t$flohmarkt-ace-cafe-rothenburg$t$, 'en', 'recurrence_text', $t$Monthly, on the first Sunday$t$),
  ($t$flohmarkt-ace-cafe-rothenburg$t$, 'fr', 'recurrence_text', $t$Chaque mois, le premier dimanche$t$),
  ($t$flohmarkt-ace-cafe-rothenburg$t$, 'it', 'recurrence_text', $t$Ogni mese, la prima domenica$t$),
  ($t$flohmarkt-glattbrugg$t$, 'de', 'description', $t$Der Rote Marktplatz in Glattbrugg, einem Ortsteil von Opfikon, wird zum Flohmarkt. Spielt das Wetter nicht mit, weiss Organisator Willi von Allmen, ob es trotzdem losgeht.$t$),
  ($t$flohmarkt-glattbrugg$t$, 'en', 'description', $t$Glattbrugg's Roter Marktplatz, in the town of Opfikon, is the setting for this flea market. If the weather turns, Willi von Allmen, who organises it, can say whether it still goes ahead.$t$),
  ($t$flohmarkt-glattbrugg$t$, 'fr', 'description', $t$Ce marché aux puces investit la Roter Marktplatz de Glattbrugg, commune d'Opfikon. Si le temps se gâte, Willi von Allmen, qui l'organise, sait dire s'il est maintenu.$t$),
  ($t$flohmarkt-glattbrugg$t$, 'it', 'description', $t$Il mercatino delle pulci si tiene sulla Roter Marktplatz, a Glattbrugg nel comune di Opfikon. Se il tempo è brutto, Willi von Allmen, che lo organizza, sa dire se si svolge comunque.$t$),
  ($t$flohmarkt-glattbrugg$t$, 'en', 'recurrence_text', $t$One Saturday in November$t$),
  ($t$flohmarkt-glattbrugg$t$, 'fr', 'recurrence_text', $t$Un samedi de novembre$t$),
  ($t$flohmarkt-glattbrugg$t$, 'it', 'recurrence_text', $t$Un sabato di novembre$t$),
  ($t$flohmarkt-hinwil$t$, 'de', 'description', $t$Zum Markt gehört ein eigenes Beizli, das Flohmibeizli, mit Mittagsmenü. Für die Musik sorgt DJ Gummistiefel.$t$),
  ($t$flohmarkt-hinwil$t$, 'en', 'description', $t$The market has its own café, the Flohmibeizli, with a lunch menu. DJ Gummistiefel takes care of the music.$t$),
  ($t$flohmarkt-hinwil$t$, 'fr', 'description', $t$Le marché a sa propre buvette, le Flohmibeizli, avec un menu de midi. DJ Gummistiefel s'occupe de la musique.$t$),
  ($t$flohmarkt-hinwil$t$, 'it', 'description', $t$Il mercatino ha un suo punto ristoro, il Flohmibeizli, con un menù di mezzogiorno. Alla musica pensa DJ Gummistiefel.$t$),
  ($t$flohmarkt-hinwil$t$, 'en', 'recurrence_text', $t$About once a month, on a Sunday$t$),
  ($t$flohmarkt-hinwil$t$, 'fr', 'recurrence_text', $t$Environ une fois par mois, un dimanche$t$),
  ($t$flohmarkt-hinwil$t$, 'it', 'recurrence_text', $t$Circa una volta al mese, di domenica$t$),
  ($t$flohmarkt-marktplatz-amriswil$t$, 'de', 'description', $t$Auf dem Amriswiler Marktplatz organisiert Toni Pfeffer diesen Flohmarkt.$t$),
  ($t$flohmarkt-marktplatz-amriswil$t$, 'en', 'description', $t$Amriswil's Marktplatz hosts this flea market, which Toni Pfeffer runs.$t$),
  ($t$flohmarkt-marktplatz-amriswil$t$, 'fr', 'description', $t$La Marktplatz d'Amriswil accueille ce marché aux puces, que Toni Pfeffer organise.$t$),
  ($t$flohmarkt-marktplatz-amriswil$t$, 'it', 'description', $t$La Marktplatz di Amriswil ospita questo mercatino delle pulci; a organizzarlo è Toni Pfeffer.$t$),
  ($t$flohmarkt-marktplatz-amriswil$t$, 'en', 'recurrence_text', $t$Monthly, on a Saturday, April to November (not in July)$t$),
  ($t$flohmarkt-marktplatz-amriswil$t$, 'fr', 'recurrence_text', $t$Chaque mois, un samedi, d'avril à novembre (sauf en juillet)$t$),
  ($t$flohmarkt-marktplatz-amriswil$t$, 'it', 'recurrence_text', $t$Ogni mese, di sabato, da aprile a novembre (escluso luglio)$t$),
  ($t$flohmarkt-schlossgut-muensingen$t$, 'de', 'description', $t$Auf dem Schlossgutplatz stehen Händler und Privathaushalte nebeneinander. Auch Kinder können hier verkaufen. Veranstalter ist Patrick Schlapbach.$t$),
  ($t$flohmarkt-schlossgut-muensingen$t$, 'en', 'description', $t$On the Schlossgutplatz, professional dealers and private households sell side by side. Children can have a stall too. The organiser is Patrick Schlapbach.$t$),
  ($t$flohmarkt-schlossgut-muensingen$t$, 'fr', 'description', $t$Sur la Schlossgutplatz, marchands professionnels et particuliers vendent côte à côte. Les enfants peuvent aussi tenir un stand. Le marché est organisé par Patrick Schlapbach.$t$),
  ($t$flohmarkt-schlossgut-muensingen$t$, 'it', 'description', $t$Sulla Schlossgutplatz espongono fianco a fianco commercianti professionisti e privati. Anche i bambini possono avere una bancarella. L'organizzatore è Patrick Schlapbach.$t$),
  ($t$flohmarkt-schlossgut-muensingen$t$, 'en', 'recurrence_text', $t$Several times a year, on a Sunday$t$),
  ($t$flohmarkt-schlossgut-muensingen$t$, 'fr', 'recurrence_text', $t$Plusieurs fois par an, un dimanche$t$),
  ($t$flohmarkt-schlossgut-muensingen$t$, 'it', 'recurrence_text', $t$Più volte all'anno, di domenica$t$),
  ($t$grosse-burgdorfer-brocante$t$, 'de', 'description', $t$Angeboten werden in der Markthalle Burgdorf Porzellan und Glas, Silber und Schmuck, Grafik, Postkarten, Möbel und Kleinantiquitäten. Einen eigenen Händlertag gibt es nicht: Profis kommen zur gleichen Zeit herein wie alle anderen.$t$),
  ($t$grosse-burgdorfer-brocante$t$, 'en', 'description', $t$Porcelain and glass, silver and jewellery, prints, postcards, furniture and small antiques are on offer in the Markthalle in Burgdorf. There is no separate trade day: dealers come in at the same time as everyone else.$t$),
  ($t$grosse-burgdorfer-brocante$t$, 'fr', 'description', $t$Porcelaine et verre, argenterie et bijoux, estampes, cartes postales, meubles et petites antiquités : voilà ce que propose la Markthalle de Berthoud. Pas de journée à part pour les professionnels, qui entrent en même temps que tout le monde.$t$),
  ($t$grosse-burgdorfer-brocante$t$, 'it', 'description', $t$Porcellana e vetro, argenteria e gioielli, stampe, cartoline, mobili e piccole antichità: ecco cosa si trova nella Markthalle a Burgdorf. Non esiste una giornata a parte per i professionisti, che entrano insieme a tutti gli altri.$t$),
  ($t$grosse-burgdorfer-brocante$t$, 'en', 'recurrence_text', $t$Every year, one weekend in November$t$),
  ($t$grosse-burgdorfer-brocante$t$, 'fr', 'recurrence_text', $t$Chaque année, un week-end de novembre$t$),
  ($t$grosse-burgdorfer-brocante$t$, 'it', 'recurrence_text', $t$Ogni anno, un fine settimana di novembre$t$),
  ($t$haerkinger-flohmi$t$, 'de', 'description', $t$Der Härkinger Flohmi findet drinnen statt, das Wetter spielt also keine Rolle. Auf den Tischen: Antiquitäten und Raritäten, Altes und Neues, auch Selbstgemachtes. Dazu gibt es ein Beizli mit Gluschtigem zu günstigen Preisen.$t$),
  ($t$haerkinger-flohmi$t$, 'en', 'description', $t$The Härkinger Flohmi is held indoors, so the weather doesn't matter. On the tables: antiques and rarities, old and new things, handmade pieces too. There's also a small café with snacks at low prices.$t$),
  ($t$haerkinger-flohmi$t$, 'fr', 'description', $t$Le Härkinger Flohmi se tient à l'intérieur, la météo n'a donc pas d'importance. Sur les tables : antiquités et raretés, objets anciens et neufs, et du fait main. Une petite buvette propose de quoi grignoter à petits prix.$t$),
  ($t$haerkinger-flohmi$t$, 'it', 'description', $t$L'Härkinger Flohmi si svolge al coperto, quindi il tempo non conta. Sui tavoli: antichità e rarità, cose vecchie e nuove, anche oggetti fatti a mano. C'è anche un piccolo bar con qualcosa da mangiare a prezzi contenuti.$t$),
  ($t$haerkinger-flohmi$t$, 'en', 'recurrence_text', $t$Every year, one Sunday in autumn$t$),
  ($t$haerkinger-flohmi$t$, 'fr', 'recurrence_text', $t$Chaque année, un dimanche d'automne$t$),
  ($t$haerkinger-flohmi$t$, 'it', 'recurrence_text', $t$Ogni anno, una domenica d'autunno$t$),
  ($t$hallenflohmarkt-aadorf$t$, 'de', 'description', $t$Marktfieber organisiert diesen Hallenflohmarkt im Gemeindezentrum. An den Ständen gibt es Flohmarktware und Handgemachtes.$t$),
  ($t$hallenflohmarkt-aadorf$t$, 'en', 'description', $t$Marktfieber runs this indoor flea market in the Gemeindezentrum (community centre). The stalls carry second-hand goods and handmade things.$t$),
  ($t$hallenflohmarkt-aadorf$t$, 'fr', 'description', $t$Marktfieber organise ce marché aux puces couvert au Gemeindezentrum (centre communal). Sur les stands : articles de brocante et objets faits main.$t$),
  ($t$hallenflohmarkt-aadorf$t$, 'it', 'description', $t$Marktfieber organizza questo mercatino al coperto nel Gemeindezentrum (centro comunale). Sulle bancarelle: articoli usati e oggetti fatti a mano.$t$),
  ($t$hallenflohmarkt-aadorf$t$, 'en', 'recurrence_text', $t$At irregular intervals, on a Sunday$t$),
  ($t$hallenflohmarkt-aadorf$t$, 'fr', 'recurrence_text', $t$À intervalles irréguliers, un dimanche$t$),
  ($t$hallenflohmarkt-aadorf$t$, 'it', 'recurrence_text', $t$A intervalli irregolari, di domenica$t$),
  ($t$hallenflohmarkt-pentorama-amriswil$t$, 'de', 'description', $t$Der Coro Tricolore di Amriswil, ein Chor, veranstaltet diesen Hallenflohmarkt im Pentorama und kümmert sich auch um Essen und Trinken. An den Ständen: Raritäten, Dinge für den Alltag und Vintage.$t$),
  ($t$hallenflohmarkt-pentorama-amriswil$t$, 'en', 'description', $t$The Coro Tricolore di Amriswil, a choir, puts on this indoor flea market at the Pentorama and also takes care of food and drink. At the stalls: rarities, everyday things and vintage.$t$),
  ($t$hallenflohmarkt-pentorama-amriswil$t$, 'fr', 'description', $t$Le Coro Tricolore di Amriswil, une chorale, organise ce marché aux puces couvert au Pentorama et s'occupe aussi de la restauration. Sur les stands : raretés, objets du quotidien et vintage.$t$),
  ($t$hallenflohmarkt-pentorama-amriswil$t$, 'it', 'description', $t$Il Coro Tricolore di Amriswil organizza questo mercatino al coperto al Pentorama e pensa anche a cibo e bevande. Sulle bancarelle: rarità, oggetti di uso quotidiano e vintage.$t$),
  ($t$hallenflohmarkt-pentorama-amriswil$t$, 'en', 'recurrence_text', $t$Every year, in November$t$),
  ($t$hallenflohmarkt-pentorama-amriswil$t$, 'fr', 'recurrence_text', $t$Chaque année, en novembre$t$),
  ($t$hallenflohmarkt-pentorama-amriswil$t$, 'it', 'recurrence_text', $t$Ogni anno, a novembre$t$),
  ($t$hallenflohmarkt-therwil$t$, 'de', 'description', $t$Die Gemeinde Therwil organisiert diesen Flohmarkt selbst. Die Stände stehen in der Mehrzweckhalle und davor. Neben ausgesuchten Antiquitäten, Raritäten und Kuriositäten gibt es Alltägliches zu günstigen Preisen.$t$),
  ($t$hallenflohmarkt-therwil$t$, 'en', 'description', $t$The municipality of Therwil runs this flea market itself. The stalls are inside the Mehrzweckhalle (multi-purpose hall) and in front of it. Next to selected antiques, rarities and curiosities, there are everyday things at low prices.$t$),
  ($t$hallenflohmarkt-therwil$t$, 'fr', 'description', $t$La commune de Therwil organise elle-même ce marché aux puces. Les stands sont installés dans la Mehrzweckhalle (salle polyvalente) et devant. À côté d'antiquités, de raretés et de curiosités choisies, on trouve des objets du quotidien à petits prix.$t$),
  ($t$hallenflohmarkt-therwil$t$, 'it', 'description', $t$È il Comune di Therwil a organizzare questo mercatino. Le bancarelle sono dentro la Mehrzweckhalle (sala multiuso) e davanti. Accanto ad antichità, rarità e curiosità scelte ci sono oggetti di uso quotidiano a buon prezzo.$t$),
  ($t$hallenflohmarkt-therwil$t$, 'en', 'recurrence_text', $t$Every year, one weekend in January$t$),
  ($t$hallenflohmarkt-therwil$t$, 'fr', 'recurrence_text', $t$Chaque année, un week-end de janvier$t$),
  ($t$hallenflohmarkt-therwil$t$, 'it', 'recurrence_text', $t$Ogni anno, un fine settimana di gennaio$t$),
  ($t$hallenflohmarkt-uster$t$, 'de', 'description', $t$Verkauft werden darf hier nur Gebrauchtes. Im Saal hat es überall Steckdosen, um Geräte vor dem Kauf zu testen. Wer mit dem Auto kommt, stellt es auf dem Stadthausplatz, im Parkhaus Iluster oder beim Zeughausareal ab – direkt beim Saal gibt es keine Plätze mehr.$t$),
  ($t$hallenflohmarkt-uster$t$, 'en', 'description', $t$Only used goods may be sold here. There are sockets all over the hall, so you can test a device before you buy it. If you come by car, park on Stadthausplatz, in the Iluster car park or at the Zeughaus site — there are no spaces at the hall itself any more.$t$),
  ($t$hallenflohmarkt-uster$t$, 'fr', 'description', $t$Seuls les objets d'occasion peuvent être vendus ici. Des prises électriques un peu partout dans la salle permettent d'essayer un appareil avant de l'acheter. En voiture, on se gare sur la Stadthausplatz, au parking Iluster ou vers le Zeughausareal : il n'y a plus de places devant la salle.$t$),
  ($t$hallenflohmarkt-uster$t$, 'it', 'description', $t$Qui si può vendere solo merce usata. Nella sala ci sono prese elettriche ovunque, così si può provare un apparecchio prima di comprarlo. In auto si parcheggia sulla Stadthausplatz, nel parcheggio Iluster o allo Zeughausareal: vicino alla sala non ci sono più posti.$t$),
  ($t$hallenflohmarkt-uster$t$, 'en', 'recurrence_text', $t$Monthly, on a Sunday, October to April$t$),
  ($t$hallenflohmarkt-uster$t$, 'fr', 'recurrence_text', $t$Chaque mois, un dimanche, d'octobre à avril$t$),
  ($t$hallenflohmarkt-uster$t$, 'it', 'recurrence_text', $t$Ogni mese, di domenica, da ottobre ad aprile$t$),
  ($t$mercalibro-bellinzona$t$, 'de', 'description', $t$Der Mercalibro ist ein Markt für gebrauchte Bücher. Daneben gibt es Comics, Zeitschriften, Drucke, Sammel- und Postkarten, Briefmarken und anderes Gedrucktes. Es verkaufen Profis wie auch Gelegenheitshändler.$t$),
  ($t$mercalibro-bellinzona$t$, 'en', 'description', $t$Mercalibro is a market for second-hand books. Alongside them you'll find comics, magazines, prints, trading cards and postcards, stamps and other printed matter. Both professional and occasional sellers take part.$t$),
  ($t$mercalibro-bellinzona$t$, 'fr', 'description', $t$Le Mercalibro est un marché du livre d'occasion. On y trouve aussi des bandes dessinées, des revues, des gravures, des cartes à collectionner et des cartes postales, des timbres et d'autres imprimés. Professionnels et vendeurs occasionnels s'y côtoient.$t$),
  ($t$mercalibro-bellinzona$t$, 'it', 'description', $t$Il Mercalibro è un mercato del libro usato. Accanto ai libri ci sono fumetti, riviste, stampe, carte da collezione e cartoline, francobolli e altri stampati. Vendono sia professionisti sia espositori occasionali.$t$),
  ($t$mercalibro-bellinzona$t$, 'en', 'recurrence_text', $t$Monthly, on the first Wednesday$t$),
  ($t$mercalibro-bellinzona$t$, 'fr', 'recurrence_text', $t$Chaque mois, le premier mercredi$t$),
  ($t$mercalibro-bellinzona$t$, 'it', 'recurrence_text', $t$Ogni mese, il primo mercoledì$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'de', 'description', $t$Gebrauchte Luxusmode und echtes Vintage: Kleider, Accessoires, Brillen und mehr, laut Veranstalterin alles wie neu. Für den Einlass braucht jede Person ein eigenes Ticket auf ihren Namen, online über Ticket Tailor. Veranstalterin ist La Ghianda von Simona Trabucco.$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'en', 'description', $t$Second-hand luxury fashion and true vintage: clothes, accessories, glasses and more, all like new, according to the organiser. Every visitor needs their own ticket in their name, booked online through Ticket Tailor. Organised by La Ghianda (Simona Trabucco).$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'fr', 'description', $t$Mode de luxe de seconde main et vrai vintage : vêtements, accessoires, lunettes et plus encore, tout comme neuf selon l'organisatrice. Chaque visiteur a besoin de son propre billet nominatif, à réserver en ligne sur Ticket Tailor. Organisé par La Ghianda (Simona Trabucco).$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'it', 'description', $t$Moda di lusso di seconda mano e vero vintage: abiti, accessori, occhiali e molto altro, tutto come nuovo secondo l'organizzatrice. Ogni visitatore deve avere il proprio biglietto nominativo, da scaricare online su Ticket Tailor. Organizza La Ghianda di Simona Trabucco.$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'en', 'recurrence_text', $t$One weekend in November$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'fr', 'recurrence_text', $t$Un week-end de novembre$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'it', 'recurrence_text', $t$Un fine settimana di novembre$t$),
  ($t$metalboerse-schweiz-zofingen$t$, 'de', 'description', $t$Im Stadtsaal Zofingen dreht sich an dieser Börse alles um Schallplatten und CDs.$t$),
  ($t$metalboerse-schweiz-zofingen$t$, 'en', 'description', $t$At the Stadtsaal in Zofingen, this fair is all about vinyl records and CDs.$t$),
  ($t$metalboerse-schweiz-zofingen$t$, 'fr', 'description', $t$Cette bourse réunit vinyles et CD dans le Stadtsaal de Zofingue.$t$),
  ($t$metalboerse-schweiz-zofingen$t$, 'it', 'description', $t$Questa borsa riunisce vinili e CD presso lo Stadtsaal di Zofingen.$t$),
  ($t$metalboerse-schweiz-zofingen$t$, 'en', 'recurrence_text', $t$One Saturday in November$t$),
  ($t$metalboerse-schweiz-zofingen$t$, 'fr', 'recurrence_text', $t$Un samedi de novembre$t$),
  ($t$metalboerse-schweiz-zofingen$t$, 'it', 'recurrence_text', $t$Un sabato di novembre$t$),
  ($t$modellbahnboerse-koeniz$t$, 'de', 'description', $t$Der Könizer Eisenbahnklub KEK veranstaltet diese Weihnachtsbörse. Neben Händlern mit Modellbahnmaterial verkauft der Klub auch Stücke im Auftrag Dritter, zum Beispiel aus Nachlässen. In der Cafeteria gibt es Kuchen, ein warmes Menü und Getränke; bis Köniz Schloss fährt der Bus 10.$t$),
  ($t$modellbahnboerse-koeniz$t$, 'en', 'description', $t$This Christmas fair is run by the KEK, Köniz's model railway club. Besides dealers with model railway equipment, the club itself sells items for other people, such as pieces from estates. The cafeteria has cake, drinks and a hot meal, and bus 10 stops at Köniz Schloss.$t$),
  ($t$modellbahnboerse-koeniz$t$, 'fr', 'description', $t$Cette bourse de Noël est organisée par le KEK, le club de modélisme ferroviaire de Köniz. À côté des marchands de matériel ferroviaire miniature, le club vend aussi des objets pour le compte d'autres personnes, notamment issus de successions. À la cafétéria : gâteaux, boissons et un plat chaud ; le bus 10 s'arrête à Köniz Schloss.$t$),
  ($t$modellbahnboerse-koeniz$t$, 'it', 'description', $t$Questa borsa di Natale la organizza il KEK, il club di fermodellismo di Köniz. Oltre ai commercianti di materiale per trenini, il club vende anche oggetti per conto di altri, per esempio da eredità. In caffetteria ci sono torte, bevande e un piatto caldo; il bus 10 ferma a Köniz Schloss.$t$),
  ($t$modellbahnboerse-koeniz$t$, 'en', 'recurrence_text', $t$Every year, one Sunday in December$t$),
  ($t$modellbahnboerse-koeniz$t$, 'fr', 'recurrence_text', $t$Chaque année, un dimanche de décembre$t$),
  ($t$modellbahnboerse-koeniz$t$, 'it', 'recurrence_text', $t$Ogni anno, una domenica di dicembre$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-buchs-sg$t$, 'de', 'description', $t$In der Mehrzweckhalle des BZB werden Spielzeug, Modellautos und Modelleisenbahnen angeboten. Organisiert wird die Börse vom Spielwaren- und Modellbaugeschäft Modellbau Kreuzlingen aus Tägerwilen.$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-buchs-sg$t$, 'en', 'description', $t$Toys, model cars and model railways change hands in the BZB's multi-purpose hall. Behind the fair is Modellbau Kreuzlingen, a toy and model shop based in Tägerwilen.$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-buchs-sg$t$, 'fr', 'description', $t$Jouets, voitures miniatures et trains miniatures : c'est ce qu'on trouve dans la salle polyvalente du BZB. Derrière cette bourse, Modellbau Kreuzlingen, une boutique de jouets et de modélisme installée à Tägerwilen.$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-buchs-sg$t$, 'it', 'description', $t$Giocattoli, modellini d'auto e trenini: ecco cosa offre questa borsa nella sala multiuso del BZB. Dietro c'è Modellbau Kreuzlingen, un negozio di giocattoli e modellismo con sede a Tägerwilen.$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-buchs-sg$t$, 'en', 'recurrence_text', $t$Once a year, on a Sunday$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-buchs-sg$t$, 'fr', 'recurrence_text', $t$Une fois par an, un dimanche$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-buchs-sg$t$, 'it', 'recurrence_text', $t$Una volta all'anno, di domenica$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-neuhausen$t$, 'de', 'description', $t$Schauplatz dieser Börse ist die Rhyfall-Halle: Hier gibt es Spielzeug, Modellautos und Modelleisenbahnen. Dahinter steht Modellbau Kreuzlingen, ein Geschäft für Spielwaren und Modellbau in Tägerwilen.$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-neuhausen$t$, 'en', 'description', $t$The Rhyfall-Halle is where toys, model cars and model railways change hands at this fair. It is organised by Modellbau Kreuzlingen, a shop for toys and models in Tägerwilen.$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-neuhausen$t$, 'fr', 'description', $t$C'est à la Rhyfall-Halle que cette bourse propose jouets, voitures miniatures et trains miniatures. Elle est l'œuvre de Modellbau Kreuzlingen, une boutique de jouets et de modélisme établie à Tägerwilen.$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-neuhausen$t$, 'it', 'description', $t$Alla Rhyfall-Halle questa borsa propone giocattoli, modellini d'auto e trenini. A organizzarla è Modellbau Kreuzlingen, un negozio di giocattoli e modellismo di Tägerwilen.$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-neuhausen$t$, 'en', 'recurrence_text', $t$Once a year, on a Sunday$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-neuhausen$t$, 'fr', 'recurrence_text', $t$Une fois par an, un dimanche$t$),
  ($t$modelleisenbahn-auto-spielzeugboerse-neuhausen$t$, 'it', 'recurrence_text', $t$Una volta all'anno, di domenica$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'de', 'description', $t$Die Stände stehen in der Einstellhalle der Landi-Agrola und draussen auf dem Gelände. Angeboten werden Antikes, Sammlerstücke und Ware aus Haushaltsauflösungen; Velo- und Elektrohändler sind nicht zugelassen. An den Ständen gibt es nichts zu essen, Sandwiches und Kaffee findest du im Tankstellenshop der Landi. Rauchen ist in der Halle nicht erlaubt.$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'en', 'description', $t$The stalls fill the Landi-Agrola's underground car park and the grounds outside. Sellers bring antiques, collectables and finds from house clearances; bicycle and electronics dealers are not admitted. No food is sold at the stalls, but the Landi petrol-station shop has sandwiches and coffee. Smoking is not allowed in the car park.$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'fr', 'description', $t$Les stands occupent le parking souterrain de la Landi-Agrola et le terrain attenant. On y trouve des antiquités, des objets de collection et des lots de débarras ; les marchands de vélos et d'électronique n'y sont pas admis. Rien à manger aux stands, mais le shop de la station-service Landi propose sandwichs et café. Interdit de fumer dans le parking.$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'it', 'description', $t$Le bancarelle occupano l'autorimessa sotterranea della Landi-Agrola e il piazzale accanto. Si trovano oggetti d'antiquariato, da collezione e da sgomberi di case; i venditori di biciclette e di elettronica non sono ammessi. Alle bancarelle non si vende cibo, ma il negozio del distributore Landi ha panini e caffè. Nell'autorimessa è vietato fumare.$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'en', 'recurrence_text', $t$Monthly, on the fourth Sunday$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'fr', 'recurrence_text', $t$Chaque mois, le quatrième dimanche$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'it', 'recurrence_text', $t$Ogni mese, la quarta domenica$t$),
  ($t$pop-up-flohmi-industrie45-zug$t$, 'de', 'description', $t$Ein Pop-up-Flohmarkt in den Räumen und auf dem Vorplatz des Jugendkulturzentrums industrie45. Am «Pimp your Clothes»-Stand kannst du mitgebrachte Kleider oder frische Fundstücke upcyceln; dazu sind ein Tattoo- und ein Henna-Artist da. Es gibt süsse und salzige Crêpes, Selbstgebackenes und eine Bar, Dari und Sophia Biermann spielen live.$t$),
  ($t$pop-up-flohmi-industrie45-zug$t$, 'en', 'description', $t$A pop-up flea market spread across the rooms and forecourt of the industrie45 youth culture centre. At the “Pimp your Clothes” stand you can upcycle clothes you bring along or have just found, and a tattoo artist and a henna artist are there too. Sweet and savoury crêpes, home baking and a bar; Dari and Sophia Biermann play live.$t$),
  ($t$pop-up-flohmi-industrie45-zug$t$, 'fr', 'description', $t$Un vide-grenier éphémère dans les salles et sur le parvis du centre culturel jeunesse industrie45. Au stand « Pimp your Clothes », vous pouvez customiser des vêtements apportés de chez vous ou tout juste dénichés ; un tatoueur et un artiste au henné sont aussi de la partie. Crêpes sucrées et salées, pâtisseries maison et un bar ; Dari et Sophia Biermann jouent en live.$t$),
  ($t$pop-up-flohmi-industrie45-zug$t$, 'it', 'description', $t$Un mercatino pop-up nelle sale e sul piazzale del centro culturale giovanile industrie45. Allo stand «Pimp your Clothes» puoi rinnovare i vestiti che porti da casa o che hai appena trovato; ci sono anche un tatuatore e un artista dell'henné. Crêpes dolci e salate, dolci fatti in casa e un bar; Dari e Sophia Biermann suonano dal vivo.$t$),
  ($t$pop-up-flohmi-industrie45-zug$t$, 'en', 'recurrence_text', $t$One-off$t$),
  ($t$pop-up-flohmi-industrie45-zug$t$, 'fr', 'recurrence_text', $t$Édition unique$t$),
  ($t$pop-up-flohmi-industrie45-zug$t$, 'it', 'recurrence_text', $t$Evento unico$t$),
  ($t$puppen-baeren-spielzeugboerse-zollikon$t$, 'de', 'description', $t$Eine Börse für antikes Spielzeug, die 1994 in Zürich begann und jetzt im Gemeindesaal Zollikon stattfindet. Zu finden sind Porzellankopfpuppen aus deutscher und französischer Produktion samt Garderobe, Sasha-Puppen, Steiff-Bären, Blechspielzeug, Puppenstuben und Krämerläden, alte Gesellschaftsspiele und Kinderbücher, Holzspielzeug aus dem Erzgebirge und Weihnachtsschmuck aus Glas, Watte und Dresdner Pappe. Auch Puppen- und Bärenkünstler verkaufen ihre eigenen Stücke. Bring eine Puppe, einen Bären oder ein Spielzeug mit: Experten schauen es sich an und schätzen den Wert, kostenlos.$t$),
  ($t$puppen-baeren-spielzeugboerse-zollikon$t$, 'en', 'description', $t$A fair for antique toys that began in Zürich in 1994 and is now held in the Gemeindesaal Zollikon. Look for porcelain-headed dolls from German and French makers with their clothes, Sasha dolls, Steiff bears, tin toys, dolls' rooms and toy shops, old board games and children's books, wooden toys from the Erzgebirge and Christmas decorations of glass, cotton wool and Dresden card. Doll and bear artists sell their own work too. Bring a doll, bear or toy along and experts will look at it and estimate its value, free of charge.$t$),
  ($t$puppen-baeren-spielzeugboerse-zollikon$t$, 'fr', 'description', $t$Une bourse de jouets anciens, née à Zurich en 1994 et installée désormais au Gemeindesaal de Zollikon. On y trouve des poupées à tête de porcelaine de fabrication allemande et française avec leurs garde-robes, des poupées Sasha, des ours Steiff, des jouets en tôle, des chambres de poupée et des épiceries miniatures, des jeux de société et des livres pour enfants anciens, des jouets en bois de l'Erzgebirge et des décorations de Noël en verre, en ouate et en carton de Dresde. Des artistes créateurs de poupées et d'ours y vendent aussi leurs pièces. Apportez une poupée, un ours ou un jouet : des experts l'examinent et en estiment la valeur, gratuitement.$t$),
  ($t$puppen-baeren-spielzeugboerse-zollikon$t$, 'it', 'description', $t$Una borsa di giocattoli antichi, nata a Zurigo nel 1994 e oggi ospitata nel Gemeindesaal di Zollikon. Si trovano bambole con testa in porcellana di produzione tedesca e francese con i loro corredi, bambole Sasha, orsetti Steiff, giocattoli di latta, case di bambola e negozietti in miniatura, vecchi giochi da tavolo e libri per bambini, giocattoli in legno dell'Erzgebirge e decorazioni natalizie di vetro, ovatta e cartone di Dresda. Anche artisti di bambole e orsetti vendono le loro creazioni. Porta una bambola, un orsetto o un giocattolo: degli esperti lo esaminano e ne stimano il valore, gratis.$t$),
  ($t$puppen-baeren-spielzeugboerse-zollikon$t$, 'en', 'recurrence_text', $t$Yearly, one Sunday in autumn$t$),
  ($t$puppen-baeren-spielzeugboerse-zollikon$t$, 'fr', 'recurrence_text', $t$Chaque année, un dimanche d'automne$t$),
  ($t$puppen-baeren-spielzeugboerse-zollikon$t$, 'it', 'recurrence_text', $t$Ogni anno, una domenica d'autunno$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'de', 'description', $t$Die Dreifachhalle Waldegg füllen inzwischen jedes Mal rund 135 Ausstellerinnen und Aussteller mit Flohmarktware und Antiquitäten. Angefangen hat der Markt in einer Einfachhalle mit 75 Ausstellern; als es dort zu eng wurde, zog er um. Sein Name verbindet die Nachnamen der beiden Familien, die ihn betreiben. Zu essen gibt es Grilliertes, Kuchen und Kaffee, dazu Getränke und im Dezember Glühwein; man kommt ohne Stufen hinein.$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'en', 'description', $t$These days around 135 sellers fill the triple hall at Waldegg each time with flea-market goods and antiques. The market started out in a single hall with 75 stalls and moved once it outgrew it. Its name joins the surnames of the two families behind it. There is grilled food, cake and coffee, plus drinks and, in December, mulled wine; the way in is step-free.$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'fr', 'description', $t$Environ 135 exposants remplissent désormais à chaque fois la triple salle Waldegg, entre puces et antiquités. Le marché a commencé dans une salle simple avec 75 exposants, puis a déménagé quand la place a manqué. Son nom associe les noms de famille des deux familles qui le tiennent. Côté restauration : grillades, gâteaux, café et boissons, et en décembre du vin chaud ; on entre de plain-pied.$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'it', 'description', $t$Ormai ogni volta circa 135 espositori riempiono la tripla palestra Waldegg con merce da mercatino e pezzi d'antiquariato. Il mercato è partito in una palestra singola con 75 espositori e ha traslocato quando lo spazio è diventato stretto. Il nome mette insieme i cognomi delle due famiglie che lo gestiscono. Da mangiare ci sono grigliate, torte e caffè, oltre alle bevande e, a dicembre, al vin brulé; si entra senza gradini.$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'en', 'recurrence_text', $t$Three times a year, a weekend in March, September and December$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'fr', 'recurrence_text', $t$Trois fois par an, un week-end en mars, septembre et décembre$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'it', 'recurrence_text', $t$Tre volte all'anno, un fine settimana a marzo, settembre e dicembre$t$),
  ($t$shoppi-flohmi-spreitenbach$t$, 'de', 'description', $t$Rund 100 Stände unter dem Dach des ShoppiParking, des Parkhauses beim Shoppi Tivoli; Regen oder Schnee sind darum kein Grund zur Absage. Die Verkäuferinnen und Verkäufer stellen direkt neben ihrem Auto aus. Es gibt ein paar Foodstände, dazu die Restaurants Hans im Glück und WonderWaffel. Flohmarktkönig führt den Markt seit 2021; zur Station Shoppi Tivoli fährt die Linie 20.$t$),
  ($t$shoppi-flohmi-spreitenbach$t$, 'en', 'description', $t$Around 100 stalls under the roof of ShoppiParking, the car park of the Shoppi Tivoli centre, so rain or snow does not call it off. Sellers set out their goods right beside their cars. There are a few food stands, plus the Hans im Glück and WonderWaffel restaurants. Flohmarktkönig has run it since 2021; line 20 stops at Shoppi Tivoli.$t$),
  ($t$shoppi-flohmi-spreitenbach$t$, 'fr', 'description', $t$Une centaine de stands à l'abri dans le ShoppiParking, le parking couvert du centre Shoppi Tivoli : pluie ou neige, il a lieu. Les vendeurs exposent juste à côté de leur voiture. Quelques stands de restauration, et les restaurants Hans im Glück et WonderWaffel. Flohmarktkönig l'organise depuis 2021 ; la ligne 20 s'arrête à Shoppi Tivoli.$t$),
  ($t$shoppi-flohmi-spreitenbach$t$, 'it', 'description', $t$Un centinaio di bancarelle al coperto nello ShoppiParking, l'autosilo del centro Shoppi Tivoli: pioggia o neve, si fa comunque. I venditori espongono proprio accanto alla loro auto. Ci sono alcuni stand gastronomici, oltre ai ristoranti Hans im Glück e WonderWaffel. Lo organizza Flohmarktkönig dal 2021; la linea 20 ferma a Shoppi Tivoli.$t$),
  ($t$shoppi-flohmi-spreitenbach$t$, 'en', 'recurrence_text', $t$About ten times a year, on a Sunday$t$),
  ($t$shoppi-flohmi-spreitenbach$t$, 'fr', 'recurrence_text', $t$Une dizaine de fois par an, le dimanche$t$),
  ($t$shoppi-flohmi-spreitenbach$t$, 'it', 'recurrence_text', $t$Una decina di volte all'anno, di domenica$t$),
  ($t$swiss-vintage-and-design-market-granges-paccot$t$, 'de', 'description', $t$Ein Markt für Vintage und Design im Forum Fribourg. Veranstalter ist Dakota Events, ein Familienbetrieb aus Poliez-Pittet, der dort auch eine Brocante und mehrere Sammlerbörsen durchführt.$t$),
  ($t$swiss-vintage-and-design-market-granges-paccot$t$, 'en', 'description', $t$A vintage and design market at Forum Fribourg. It is run by Dakota Events, a family business from Poliez-Pittet that also holds a brocante and several collector fairs in the same venue.$t$),
  ($t$swiss-vintage-and-design-market-granges-paccot$t$, 'fr', 'description', $t$Un marché vintage et design au Forum Fribourg. Il est organisé par Dakota Events, une entreprise familiale de Poliez-Pittet qui y tient aussi une brocante et plusieurs bourses de collection.$t$),
  ($t$swiss-vintage-and-design-market-granges-paccot$t$, 'it', 'description', $t$Un mercato di vintage e design al Forum Fribourg. Lo organizza Dakota Events, un'azienda di famiglia di Poliez-Pittet che vi tiene anche una brocante e diverse borse per collezionisti.$t$),
  ($t$swiss-vintage-and-design-market-granges-paccot$t$, 'en', 'recurrence_text', $t$One weekend in March$t$),
  ($t$swiss-vintage-and-design-market-granges-paccot$t$, 'fr', 'recurrence_text', $t$Un week-end de mars$t$),
  ($t$swiss-vintage-and-design-market-granges-paccot$t$, 'it', 'recurrence_text', $t$Un fine settimana di marzo$t$),
  ($t$vide-grenier-brocante-les-brenets$t$, 'de', 'description', $t$Vide-grenier und Brocante zugleich: Diesen Markt organisiert die Association pour les Enfants des Brenets. Wer Hunger hat, findet an der Buvette Raclette, Sandwiches und Gebäck.$t$),
  ($t$vide-grenier-brocante-les-brenets$t$, 'en', 'description', $t$The Association pour les Enfants des Brenets runs this market, a vide-grenier with brocante. At the bar there is raclette, along with sandwiches and pastries.$t$),
  ($t$vide-grenier-brocante-les-brenets$t$, 'fr', 'description', $t$C'est l'Association pour les Enfants des Brenets qui met sur pied ce vide-grenier doublé d'une brocante. On peut se restaurer à la buvette : raclette, sandwichs et pâtisseries.$t$),
  ($t$vide-grenier-brocante-les-brenets$t$, 'it', 'description', $t$A organizzarlo è l'Association pour les Enfants des Brenets: un vide-grenier che è anche brocante. Alla buvette si trovano raclette, panini e dolci.$t$),
  ($t$vide-grenier-brocante-les-brenets$t$, 'en', 'recurrence_text', $t$One Saturday in November$t$),
  ($t$vide-grenier-brocante-les-brenets$t$, 'fr', 'recurrence_text', $t$Un samedi de novembre$t$),
  ($t$vide-grenier-brocante-les-brenets$t$, 'it', 'recurrence_text', $t$Un sabato di novembre$t$),
  ($t$vide-grenier-villars-tiercelin$t$, 'de', 'description', $t$In Villars-Tiercelin (Jorat-Menthue) ist die Grande salle Schauplatz eines Vide-greniers.$t$),
  ($t$vide-grenier-villars-tiercelin$t$, 'en', 'description', $t$In Villars-Tiercelin (Jorat-Menthue), the Grande salle hosts a vide-grenier.$t$),
  ($t$vide-grenier-villars-tiercelin$t$, 'fr', 'description', $t$À Villars-Tiercelin (Jorat-Menthue), la grande salle accueille un vide-grenier.$t$),
  ($t$vide-grenier-villars-tiercelin$t$, 'it', 'description', $t$A Villars-Tiercelin (Jorat-Menthue) la Grande salle ospita un vide-grenier.$t$),
  ($t$vide-grenier-villars-tiercelin$t$, 'en', 'recurrence_text', $t$One Sunday in November$t$),
  ($t$vide-grenier-villars-tiercelin$t$, 'fr', 'recurrence_text', $t$Un dimanche de novembre$t$),
  ($t$vide-grenier-villars-tiercelin$t$, 'it', 'recurrence_text', $t$Una domenica di novembre$t$),
  ($t$vinylboerse-villa-flora-wald$t$, 'de', 'description', $t$Eine Schallplattenbörse in der herrschaftlichen Villa Flora, seit 2022. Händler bringen gebrauchte und neue Platten mit, LPs, Singles und Schellack, dazu Kassetten, CDs und Abspielgeräte. Das Bistro bietet den ganzen Tag Essen und Getränke.$t$),
  ($t$vinylboerse-villa-flora-wald$t$, 'en', 'description', $t$A record fair in the stately Villa Flora, held since 2022. Dealers bring used and new records, LPs, singles and shellac, along with cassettes, CDs and players. The bistro serves food and drinks all day.$t$),
  ($t$vinylboerse-villa-flora-wald$t$, 'fr', 'description', $t$Une bourse aux disques dans la maison de maître Villa Flora, depuis 2022. Les marchands proposent des disques d'occasion et neufs, 33 tours, 45 tours et 78 tours en gomme-laque, ainsi que des cassettes, des CD et des lecteurs. Le bistrot sert à manger et à boire toute la journée.$t$),
  ($t$vinylboerse-villa-flora-wald$t$, 'it', 'description', $t$Una borsa del disco nella signorile Villa Flora, dal 2022. I commercianti portano dischi usati e nuovi, LP, singoli e dischi in gommalacca, oltre a cassette, CD e apparecchi per l'ascolto. Il bistrot serve da mangiare e da bere tutto il giorno.$t$),
  ($t$vinylboerse-villa-flora-wald$t$, 'en', 'recurrence_text', $t$Twice a year, a Sunday in May/June and in October/November$t$),
  ($t$vinylboerse-villa-flora-wald$t$, 'fr', 'recurrence_text', $t$Deux fois par an, un dimanche en mai/juin et en octobre/novembre$t$),
  ($t$vinylboerse-villa-flora-wald$t$, 'it', 'recurrence_text', $t$Due volte all'anno, una domenica a maggio/giugno e a ottobre/novembre$t$),
  ($t$weihnachtsdekomarkt-hardmatt-strengelbach$t$, 'de', 'description', $t$Ein Weihnachtsdekomarkt im Flohmarkt des Seniorenzentrums Hardmatt, in den Kellerräumen, die über eine Treppe erreichbar sind. Im Angebot ist, was Leute abgegeben haben: Kupferkannen, handbemaltes Geschirr, Bilder, altes Spielzeug und Alltägliches. Über die angeschriebenen Preise lässt sich reden.$t$),
  ($t$weihnachtsdekomarkt-hardmatt-strengelbach$t$, 'en', 'description', $t$A Christmas decorations market in the Hardmatt senior centre's flea market, in basement rooms reached by a flight of stairs. On offer is what people have handed in: copper jugs, hand-painted tableware, pictures, old toys and everyday things. Marked prices are open to haggling.$t$),
  ($t$weihnachtsdekomarkt-hardmatt-strengelbach$t$, 'fr', 'description', $t$Un marché de décorations de Noël au marché aux puces du centre pour seniors Hardmatt, dans des locaux en sous-sol accessibles par un escalier. On y trouve ce que les gens ont déposé : cruches en cuivre, vaisselle peinte à la main, tableaux, vieux jouets et objets du quotidien. Les prix affichés se discutent.$t$),
  ($t$weihnachtsdekomarkt-hardmatt-strengelbach$t$, 'it', 'description', $t$Un mercatino di decorazioni natalizie nel mercatino dell'usato del centro anziani Hardmatt, in locali seminterrati raggiungibili da una scala. In vendita c'è ciò che la gente ha portato: brocche di rame, stoviglie dipinte a mano, quadri, vecchi giocattoli e oggetti di tutti i giorni. Sui prezzi esposti si può trattare.$t$),
  ($t$weihnachtsdekomarkt-hardmatt-strengelbach$t$, 'en', 'recurrence_text', $t$Three days in November$t$),
  ($t$weihnachtsdekomarkt-hardmatt-strengelbach$t$, 'fr', 'recurrence_text', $t$Trois jours en novembre$t$),
  ($t$weihnachtsdekomarkt-hardmatt-strengelbach$t$, 'it', 'recurrence_text', $t$Tre giorni a novembre$t$),
  ($t$zuercher-schallplatten-cd-boerse$t$, 'de', 'description', $t$Eine Schallplatten- und CD-Börse im Theatersaal des Volkshauses Zürich. Veranstalter ist BLUTT Records, ein Secondhand-Plattenladen an der Limmatstrasse, den es seit 1995 gibt.$t$),
  ($t$zuercher-schallplatten-cd-boerse$t$, 'en', 'description', $t$A record and CD fair in the Theatersaal of the Volkshaus Zürich. It is run by BLUTT Records, a second-hand record shop on Limmatstrasse that has been trading since 1995.$t$),
  ($t$zuercher-schallplatten-cd-boerse$t$, 'fr', 'description', $t$Une bourse aux disques et CD dans le Theatersaal du Volkshaus de Zurich. Elle est organisée par BLUTT Records, un disquaire d'occasion de la Limmatstrasse ouvert depuis 1995.$t$),
  ($t$zuercher-schallplatten-cd-boerse$t$, 'it', 'description', $t$Una borsa di dischi e CD nel Theatersaal del Volkshaus di Zurigo. La organizza BLUTT Records, un negozio di dischi usati in Limmatstrasse attivo dal 1995.$t$),
  ($t$zuercher-schallplatten-cd-boerse$t$, 'en', 'recurrence_text', $t$Twice a year, on Sundays$t$),
  ($t$zuercher-schallplatten-cd-boerse$t$, 'fr', 'recurrence_text', $t$Deux fois par an, le dimanche$t$),
  ($t$zuercher-schallplatten-cd-boerse$t$, 'it', 'recurrence_text', $t$Due volte all'anno, di domenica$t$);
