-- The 40 Swiss markets brought hidden from v1 on 2026-10-09: their texts in our own words,
-- written from the organisers' pages in four locales (intake/descriptions-v1-winter/out-*.json,
-- sources and quotes there), and their rhythm lines in en/fr/it. Then every one with a photo and
-- a text is published. v1's descriptions are replaced, not kept: the same text on two live sites
-- is what the 8 October rewrite removed everywhere else.

begin;

create temporary table new_text (slug text, locale text, field text, value text) on commit drop;

do $$
declare n int;
begin
  if not exists (select 1 from public.markets) then return; end if;
  update public.texts t set value = d.value, updated_at = now()
    from public.markets m, new_text d
   where t.entity_type = 'market' and t.entity_id = m.id and t.field = d.field and m.slug = d.slug and t.locale = d.locale;
  select 'market', m.id, d.locale, d.field, d.value from new_text d join public.markets m on m.slug = d.slug
   where not exists (select 1 from public.texts t where t.entity_type = 'market' and t.entity_id = m.id and t.field = d.field and t.locale = d.locale);
  update public.markets set status = 'active', updated_at = now()
   where status = 'unverified' and image_url is not null and slug in ('bourse-jouets-collection-fribourg-granges-paccot', 'bourse-jouets-collection-geneve-le-grand-saconnex', 'bourse-photo-vieux-papiers-fribourg-granges-paccot', 'bourse-vinyls-cd-geneve-le-grand-saconnex', 'brocante-de-fribourg-granges-paccot', 'brocante-vide-grenier-55-plus-ecublens', 'comicboerse-zuerich', 'enter-modellbau-boerse-derendingen', 'enter-retrotechnikmarkt-derendingen', 'enter-vinyl-film-buecher-boerse-derendingen', 'floh-sammler-antikmarkt-grabs', 'floh-sammler-antikmarkt-romanshorn', 'flohmarkt-ace-cafe-rothenburg', 'flohmarkt-glattbrugg', 'flohmarkt-hinwil', 'flohmarkt-marktplatz-amriswil', 'flohmarkt-schlossgut-muensingen', 'grosse-burgdorfer-brocante', 'haerkinger-flohmi', 'hallenflohmarkt-aadorf', 'hallenflohmarkt-pentorama-amriswil', 'hallenflohmarkt-therwil', 'hallenflohmarkt-uster', 'mercalibro-bellinzona', 'mercatino-lusso-vintage-lugano', 'metalboerse-schweiz-zofingen', 'modellbahnboerse-koeniz', 'modelleisenbahn-auto-spielzeugboerse-buchs-sg', 'modelleisenbahn-auto-spielzeugboerse-neuhausen', 'nostalgie-flohmarkt-lyssach', 'pop-up-flohmi-industrie45-zug', 'puppen-baeren-spielzeugboerse-zollikon', 'romeo-hallenflohmarkt-muenchwilen', 'shoppi-flohmi-spreitenbach', 'swiss-vintage-and-design-market-granges-paccot', 'vide-grenier-brocante-les-brenets', 'vide-grenier-villars-tiercelin', 'vinylboerse-villa-flora-wald', 'zuercher-schallplatten-cd-boerse');
  get diagnostics n = row_count;
  raise notice 'published %', n;
end $$;

commit;
